PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE users (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT DEFAULT 'employee', created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL UNIQUE,
    created_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE project_tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL,
    task_name TEXT NOT NULL,
    created_at TEXT DEFAULT (datetime('now')),
    FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE,
    UNIQUE(project_id, task_name)
);
CREATE TABLE IF NOT EXISTS "daily_status_entries" (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    employee_id INTEGER NOT NULL,
    project_id INTEGER NOT NULL,
    entry_date TEXT NOT NULL,
    start_time TEXT NOT NULL,
    end_time TEXT NOT NULL,
    duration_minutes INTEGER,
    task_description TEXT NOT NULL,
    task_name TEXT DEFAULT NULL,
    module_name TEXT DEFAULT NULL,
    is_email_sent TEXT CHECK(is_email_sent IN ('true', 'false')) DEFAULT 'false',
    created_at TEXT DEFAULT (datetime('now')),
    updated_at TEXT DEFAULT (datetime('now')),
    FOREIGN KEY (employee_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_user_entry_date ON daily_status_entries (employee_id, entry_date);
CREATE TRIGGER update_daily_status_entries_timestamp
AFTER UPDATE ON daily_status_entries
BEGIN
    UPDATE daily_status_entries SET updated_at = datetime('now') WHERE id = NEW.id;
END;
